#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

template <typename scalar_t>
__global__ void fused_scaled_dot_product_attention_kernel(
    const scalar_t* __restrict__ Q,
    const scalar_t* __restrict__ K,
    const scalar_t* __restrict__ V,
    scalar_t* __restrict__ Out,
    const int B,
    const int H,
    const int S,
    const int D)
{
    // each thread computes one output element (b, h, i, d)
    const int total_threads = B * H * S * D;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_threads) return;

    // decode indices
    int tmp = idx;
    const int d = tmp % D; tmp /= D;
    const int i = tmp % S; tmp /= S;
    const int h = tmp % H; tmp /= H;
    const int b = tmp;

    // pointers offsets
    const int q_offset = ((b * H + h) * S + i) * D;
    const int out_offset = q_offset + d;

    const float scale = rsqrtf((float)D); // 1/sqrt(D)

    // First pass: find max score for numerical stability
    float max_score = -FLT_MAX;
    for (int j = 0; j < S; ++j) {
        float dot = 0.0f;
        const int k_offset = ((b * H + h) * S + j) * D;
        for (int dd = 0; dd < D; ++dd) {
            float q_val = static_cast<float>(Q[q_offset + dd]);
            float k_val = static_cast<float>(K[k_offset + dd]);
            dot += q_val * k_val;
        }
        dot *= scale;
        if (dot > max_score) max_score = dot;
    }

    // Second pass: compute sum of exp(score - max)
    float sum_exp = 0.0f;
    for (int j = 0; j < S; ++j) {
        float dot = 0.0f;
        const int k_offset = ((b * H + h) * S + j) * D;
        for (int dd = 0; dd < D; ++dd) {
            float q_val = static_cast<float>(Q[q_offset + dd]);
            float k_val = static_cast<float>(K[k_offset + dd]);
            dot += q_val * k_val;
        }
        dot *= scale;
        sum_exp += expf(dot - max_score);
    }

    // Third pass: compute weighted sum over V using softmax probabilities
    float out_val = 0.0f;
    for (int j = 0; j < S; ++j) {
        float dot = 0.0f;
        const int k_offset = ((b * H + h) * S + j) * D;
        for (int dd = 0; dd < D; ++dd) {
            float q_val = static_cast<float>(Q[q_offset + dd]);
            float k_val = static_cast<float>(K[k_offset + dd]);
            dot += q_val * k_val;
        }
        dot *= scale;
        float prob = expf(dot - max_score) / sum_exp;

        const int v_offset = ((b * H + h) * S + j) * D + d;
        out_val += prob * static_cast<float>(V[v_offset]);
    }

    Out[out_offset] = static_cast<scalar_t>(out_val);
}

torch::Tensor fused_scaled_dot_product_attention(torch::Tensor Q,
                                                 torch::Tensor K,
                                                 torch::Tensor V) {
    const auto B = Q.size(0);
    const auto H = Q.size(1);
    const auto S = Q.size(2);
    const auto D = Q.size(3);

    auto Out = torch::empty_like(Q);

    const int threads = 256;
    const int total = B * H * S * D;
    const int blocks = (total + threads - 1) / threads;

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(Q.scalar_type(), "fused_sdpa_kernel", ([&] {
        fused_scaled_dot_product_attention_kernel<scalar_t><<<blocks, threads>>>(
            Q.data_ptr<scalar_t>(),
            K.data_ptr<scalar_t>(),
            V.data_ptr<scalar_t>(),
            Out.data_ptr<scalar_t>(),
            B, H, S, D);
    }));

    cudaDeviceSynchronize();
    return Out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_sdpa", &fused_scaled_dot_product_attention, "Fused Scaled Dot-Product Attention (CUDA)");
}
'''

# Compile the inline extension
sdpa_ext = load_inline(name='fused_sdpa',
                       cpp_sources='',
                       cuda_sources=cuda_source,
                       functions=['fused_sdpa'],
                       verbose=False)

