    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Ensure inputs are half precision and on CUDA
        Q = Q.to(dtype=torch.float16, device='cuda')
        K = K.to(dtype=torch.float16, device='cuda')
        V = V.to(dtype=torch.float16, device='cuda')
        out = sdpa_ext.fused_sdpa(Q, K, V)
        return out

